pm.test("GH-008-01: HTTP status is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response content type is JSON", function () {
    pm.expect(
        pm.response.headers.get("Content-Type")
    ).to.include("application/json");
});

const repository = pm.response.json();

pm.test("Repository identity is correct", function () {
    pm.expect(repository.id).to.eql(1296269);
    pm.expect(repository.name).to.eql("Hello-World");
    pm.expect(repository.full_name).to.eql("octocat/Hello-World");
    pm.expect(repository.owner.login).to.eql("octocat");
});

pm.test("Repository is public", function () {
    pm.expect(repository.private).to.eql(false);
});

pm.test("GH-008-02: HTTP status is 404", function () {
    pm.response.to.have.status(404);
});

pm.test("Response content type is JSON", function () {
    pm.expect(
        pm.response.headers.get("Content-Type")
    ).to.include("application/json");
});

pm.test("Error message is Not Found", function () {
    const error = pm.response.json();
    pm.expect(error.message).to.eql("Not Found");
});

pm.test("Error status field is 404", function () {
    const error = pm.response.json();
    pm.expect(error.status).to.eql("404");
});

